SELECT co.id, co.no, co.user_id AS userId, u.nickname AS userName, co.card_id AS cardId, cc.name AS cardName, co.amount, co.pay_status AS payStatus, co.pay_time AS payTime, co.active_time AS activeTime, co.invoice_status AS invoiceStatus, co.archive_time AS archiveTime, co.creator, co.create_time AS createTime, co.update_time AS updateTime FROM card_order co LEFT JOIN user_info u ON co.user_id = u.id AND u.deleted = 0 LEFT JOIN card_config cc ON co.card_id = cc.id AND cc.deleted = 0 WHERE co.deleted = 0 AND co.id IN
#{id}
ORDER BY co.id DESC
